662	/**
663	 * Globale Suche über alles, was der Nutzer sehen darf.
664	 * Rückgabe: { q, treffer: [{ art, id, titel, untertitel, href }] } – max. `limit` je Art.
665	 */
666	export async function suchen(n, { q, limit = 6 } = {}) {
667	  if (!n) throw new PlattformFehler(401, "Bitte melden Sie sich an.");
668	  const anfrage = anfrageBereinigen(q);
669	  const max = Math.min(20, Math.max(1, Number(limit) || 6));
670	  if (anfrage.length < SUCHE_MIN) return { q: anfrage, treffer: [] };
671	  const admin = istAdmin(n);
672	  const leer = () => [];
673	
674	  const [vorgaenge, flaechen, projekte, boerse, threads, nutzer] = await Promise.all([
675	    demo.vorgaenge(n, { alle: admin }).catch(leer),
676	    hat(n, "flaeche", "landwirt") ? demo.flaechen(n, { alle: admin }).catch(leer) : [],
677	    hat(n, "anbieter") ? demo.projekte(n, { alle: admin }).catch(leer) : [],
678	    hat(n, "investor") ? demo.boerse(n, {}).then((b) => b.projekte).catch(leer) : [],
679	    demo.nachrichtenThreads(n).catch(leer),
680	    admin ? demo.nutzerListe(n, {}).catch(leer) : [],
681	  ]);
682	
683	  const quellen = [
684	    trefferFlaechen(flaechen, admin),
685	    trefferProjekte(projekte, admin),
686	    trefferVorgaenge(vorgaenge, admin),
687	    trefferThreads(threads),
688	    trefferBoerse(boerse),
689	    trefferNutzer(nutzer),
690	  ];
691	  const treffer = quellen
692	    .flatMap((liste) => rangieren(liste, anfrage, (e) => e.felder, { limit: max }))
693	    .filter((t) => istPortalPfad(t.href))
694	    .map(({ felder: _f, ...t }) => t);
695	  return { q: anfrage, treffer };
696	}
