      ["Regeln erst im Testlauf prüfen, dann aktivieren.", "Revisionsprotokoll: Hash-Kette regelmäßig prüfen."],
      [{ href: "/portal/admin/automationen", label: "Automationen" }, { href: "/portal/admin/berichte", label: "Berichte" }]),
