"use client";

// Inline-Formulare der Onboarding-Assistenten (Team B1): Profil, Untertyp, Suchprofil, Ticket & Struktur, Fläche/Dach,
// Benachrichtigungen. Gespeichert wird ausschließlich über die bestehenden Portal-APIs (Rechte/Validierung dort);
// danach lädt der Assistent den Stand aus echten Daten neu.

import { useId, useState } from "react";
import Button from "@/components/ui/Button";
import { cn } from "@/components/ui/cn";
import { senden } from "@/lib/plattform/client";
import { BENACHRICHTIGUNG_ARTEN, LAENDER, PROJEKT_TYPEN, benachrichtigungArtenFuer, mailEinstellungenStandard } from "@/lib/plattform/konstanten";
import { DEAL_STRUKTUREN, ESG_ANFORDERUNGEN, FINANZIERUNGSWEISEN } from "@/lib/plattform/fach/suchprofil";
import { PHASEN } from "@/lib/invest/markt";
import { UNTERTYP_ZU_INVESTOR_TYP } from "@/lib/plattform/onboarding/pfade";
import { eingabe, auswahlfeld, labelKlasse, Chip, FehlerBox } from "@/components/Portal/felder";
import { FeldFehler, fehlerText, regeln, useFeldPruefung, zahlWert } from "../pruefung";

/** Gemeinsamer Rahmen: Absenden → API → onGespeichert() */
function useSenden(onGespeichert) {
  const [laeuft, setLaeuft] = useState(false);
  const [fehler, setFehler] = useState("");
  async function los(fn) {
    setLaeuft(true);
    setFehler("");
    try {
      await fn();
      await onGespeichert();
    } catch (e) {
      setFehler(fehlerText(e));
    } finally {
      setLaeuft(false);
    }
  }
  return { laeuft, fehler, los };
}

function Absenden({ laeuft, text = "Speichern und weiter" }) {
  return (
    <div className="mt-6 flex justify-end">
      <Button type="submit" disabled={laeuft} pfeil>{laeuft ? "Wird gespeichert …" : text}</Button>
    </div>
  );
}

function Textfeld({ id, k, label, w, setze, p, props = {}, klasse = "" }) {
  return (
    <div className={cn("min-w-0", klasse)}>
      <label htmlFor={`${id}-${k}`} className={labelKlasse}>{label}</label>
      <input id={`${id}-${k}`} value={w[k]} onChange={(e) => setze(k, e.target.value)} className={cn(eingabe, p?.fehler[k] && "ring-2 ring-red-400")} {...(p ? p.feldProps(k, `${id}-${k}`, w) : {})} {...props} />
      {p && <FeldFehler id={`${id}-${k}`} text={p.fehler[k]} />}
    </div>
  );
}

// ---------------------------------------------------------------- Untertyp

export function UntertypWahl({ schritt, pfad, onWahl }) {
  const [laeuft, setLaeuft] = useState("");
  const [fehler, setFehler] = useState("");
  return (
    <div>
      <ul className="mt-5 grid gap-3 sm:grid-cols-2" role="list">
        {pfad.untertypen.map((u) => {
          const aktiv = pfad.untertyp === u.id;
          return (
            <li key={u.id}>
              <button
                type="button"
                aria-pressed={aktiv}
                disabled={!!laeuft}
                onClick={async () => {
                  setLaeuft(u.id);
                  setFehler("");
                  try {
                    await onWahl(u.id);
                  } catch (e) {
                    setFehler(fehlerText(e));
                  } finally {
                    setLaeuft("");
                  }
                }}
                className={cn("flex h-full w-full flex-col items-start gap-1 rounded-2xl p-4 text-left ring-1 ring-inset transition-colors", aktiv ? "bg-ov-50 ring-2 ring-ov-500" : "bg-sand-50 ring-ink-200/70 hover:ring-ov-300")}
              >
                <span className="font-semibold text-ink-900">{u.label}{laeuft === u.id ? " …" : ""}</span>
                {u.text && <span className="text-[13.5px] leading-snug text-ink-600">{u.text}</span>}
              </button>
            </li>
          );
        })}
      </ul>
      {schritt.erledigt && !pfad.untertypGewaehlt && <p className="mt-3 text-[13px] text-ink-500">Vorgeschlagen aus Ihren Daten – bitte bestätigen oder ändern.</p>}
      <div className="mt-4"><FehlerBox>{fehler}</FehlerBox></div>
    </div>
  );
}

// ---------------------------------------------------------------- Profil

const PROFIL_SCHEMA = (firmaPflicht) => ({
  vorname: [regeln.pflicht("Bitte geben Sie Ihren Vornamen an."), regeln.laenge(1, 80, "Der Vorname")],
  nachname: [regeln.pflicht("Bitte geben Sie Ihren Nachnamen an."), regeln.laenge(1, 80, "Der Nachname")],
  telefon: [regeln.telefon()],
  firma: [...(firmaPflicht ? [regeln.pflicht("Bitte geben Sie die Firma bzw. Organisation an.")] : []), regeln.laenge(0, 120, "Der Name")],
});

export function ProfilFormular({ nutzer, schritt, untertyp, onGespeichert }) {
  const id = useId();
  const firmaPflicht = !!schritt.firmaLabel && untertyp !== "privat";
  const [w, setW] = useState({ vorname: nutzer.vorname || "", nachname: nutzer.nachname || "", telefon: nutzer.telefon || "", firma: nutzer.firma || "" });
  const p = useFeldPruefung(PROFIL_SCHEMA(firmaPflicht));
  const s = useSenden(onGespeichert);
  const setze = (k, v) => {
    const neu = { ...w, [k]: v };
    setW(neu);
    p.aendern(k, neu);
  };
  return (
    <form noValidate onSubmit={(e) => { e.preventDefault(); if (p.alles(w)) s.los(() => senden("/api/portal/profil", { method: "PATCH", body: w })); }}>
      <div className="mt-5 grid gap-4 sm:grid-cols-2">
        <Textfeld id={id} k="vorname" label="Vorname *" w={w} setze={setze} p={p} props={{ autoComplete: "given-name", required: true }} />
        <Textfeld id={id} k="nachname" label="Nachname *" w={w} setze={setze} p={p} props={{ autoComplete: "family-name", required: true }} />
        <Textfeld id={id} k="telefon" label="Telefon" w={w} setze={setze} p={p} props={{ autoComplete: "tel", inputMode: "tel", placeholder: "+49 …" }} />
        <Textfeld id={id} k="firma" label={`${schritt.firmaLabel || "Firma / Betrieb"}${firmaPflicht ? " *" : " (optional)"}`} w={w} setze={setze} p={p} props={{ autoComplete: "organization" }} />
      </div>
      <p className="mt-3 text-[12.5px] text-ink-500">* Pflichtangabe. E-Mail-Adresse: {nutzer.email}</p>
      <div className="mt-4"><FehlerBox>{s.fehler}</FehlerBox></div>
      <Absenden laeuft={s.laeuft} />
    </form>
  );
}

// ---------------------------------------------------------------- Suchprofil (Investor)

const SUCH_SCHEMA = {
  mwpMin: [regeln.zahl({ min: 0, max: 5000, einheit: "MWp", was: "Die Mindestgröße" })],
  mwpMax: [regeln.zahl({ min: 0, max: 5000, einheit: "MWp", was: "Die Höchstgröße" }), regeln.bereich("mwpMin", "Die Mindestgröße")],
};

const umschalten = (setW, k, wert) => setW((x) => ({ ...x, [k]: x[k].includes(wert) ? x[k].filter((y) => y !== wert) : [...x[k], wert] }));
const n0 = (x) => (zahlWert(x) === null ? null : zahlWert(x));

export function SuchprofilFormular({ nutzer, untertyp, onGespeichert }) {
  const id = useId();
  const v = nutzer.suchprofil || {};
  const [w, setW] = useState({ typen: v.typen || [], laender: v.laender || [], phasen: v.phasen || [], mwpMin: v.mwpMin ?? "", mwpMax: v.mwpMax ?? "", benachrichtigen: v.benachrichtigen ?? true });
  const p = useFeldPruefung(SUCH_SCHEMA);
  const s = useSenden(onGespeichert);
  const setze = (k, x) => {
    const neu = { ...w, [k]: x };
    setW(neu);
    p.aendern(k, neu);
    if (k === "mwpMin") p.aendern("mwpMax", neu);
  };
  const absenden = (e) => {
    e.preventDefault();
    if (!p.alles(w)) return;
    const investorTyp = UNTERTYP_ZU_INVESTOR_TYP[untertyp] && !v.investorTyp ? UNTERTYP_ZU_INVESTOR_TYP[untertyp] : v.investorTyp;
    s.los(() => senden("/api/portal/suchprofil", { method: "PUT", body: { ...v, typen: w.typen, laender: w.laender, phasen: w.phasen, mwpMin: n0(w.mwpMin), mwpMax: n0(w.mwpMax), benachrichtigen: w.benachrichtigen, investorTyp } }));
  };
  return (
    <form noValidate onSubmit={absenden}>
      <fieldset className="mt-5">
        <legend className={labelKlasse}>Projekttypen</legend>
        <div className="flex flex-wrap gap-2">{Object.entries(PROJEKT_TYPEN).map(([k, t]) => <Chip key={k} name="typen" value={k} checked={w.typen.includes(k)} onChange={() => umschalten(setW, "typen", k)}>{t}</Chip>)}</div>
      </fieldset>
      <fieldset className="mt-4">
        <legend className={labelKlasse}>Länder</legend>
        <div className="flex flex-wrap gap-2">{Object.entries(LAENDER).map(([k, t]) => <Chip key={k} name="laender" value={k} checked={w.laender.includes(k)} onChange={() => umschalten(setW, "laender", k)}>{t}</Chip>)}</div>
      </fieldset>
      <fieldset className="mt-4">
        <legend className={labelKlasse}>Projektphasen</legend>
        <div className="flex flex-wrap gap-2">{PHASEN.map((ph) => <Chip key={ph.id} name="phasen" value={ph.id} checked={w.phasen.includes(ph.id)} onChange={() => umschalten(setW, "phasen", ph.id)}>{ph.kurz}</Chip>)}</div>
      </fieldset>
      <div className="mt-4 grid gap-4 sm:grid-cols-2">
        <Textfeld id={id} k="mwpMin" label="Leistung ab (MWp)" w={w} setze={setze} p={p} props={{ inputMode: "decimal", placeholder: "z. B. 5" }} />
        <Textfeld id={id} k="mwpMax" label="Leistung bis (MWp)" w={w} setze={setze} p={p} props={{ inputMode: "decimal", placeholder: "z. B. 50" }} />
      </div>
      <label className="mt-4 flex items-start gap-3 text-[14px] text-ink-700">
        <input type="checkbox" checked={w.benachrichtigen} onChange={(e) => setW((x) => ({ ...x, benachrichtigen: e.target.checked }))} className="mt-0.5 h-5 w-5 rounded accent-ov-600" />
        <span>Bei neuen passenden Projekten benachrichtigen (ab 70 % Passung, im Profil einstellbar).</span>
      </label>
      <div className="mt-4"><FehlerBox>{s.fehler}</FehlerBox></div>
      <Absenden laeuft={s.laeuft} text="Suchprofil speichern" />
    </form>
  );
}

// ---------------------------------------------------------------- Ticket & Struktur (Investor)

const TICKET_SCHEMA = {
  ticketMin: [regeln.zahl({ min: 0, max: 1e10, einheit: "€", was: "Das Mindestticket" })],
  ticketMax: [regeln.zahl({ min: 0, max: 1e10, einheit: "€", was: "Das Höchstticket" }), regeln.bereich("ticketMin", "Das Mindestticket")],
  renditeZielPct: [regeln.zahl({ min: 0, max: 30, einheit: "%", was: "Das Rendite-Ziel" })],
};

export function TicketFormular({ nutzer, untertyp, onGespeichert }) {
  const id = useId();
  const v = nutzer.suchprofil || {};
  const [w, setW] = useState({
    ticketMin: v.ticketMin ?? "", ticketMax: v.ticketMax ?? "", renditeZielPct: v.renditeZielPct ?? "", renditeBasis: v.renditeBasis || "ek",
    dealStrukturen: v.dealStrukturen || [], finanzierung: v.finanzierung || "", esg: v.esg || [],
  });
  const p = useFeldPruefung(TICKET_SCHEMA);
  const s = useSenden(onGespeichert);
  const setze = (k, x) => {
    const neu = { ...w, [k]: x };
    setW(neu);
    p.aendern(k, neu);
    if (k === "ticketMin") p.aendern("ticketMax", neu);
  };
  const absenden = (e) => {
    e.preventDefault();
    if (!p.alles(w)) return;
    s.los(() => senden("/api/portal/suchprofil", { method: "PUT", body: { ...v, ticketMin: n0(w.ticketMin), ticketMax: n0(w.ticketMax), renditeZielPct: n0(w.renditeZielPct), renditeBasis: w.renditeBasis, dealStrukturen: w.dealStrukturen, finanzierung: w.finanzierung, esg: w.esg } }));
  };
  return (
    <form noValidate onSubmit={absenden}>
      <div className="mt-5 grid gap-4 sm:grid-cols-2">
        <Textfeld id={id} k="ticketMin" label="Eigenkapital je Transaktion ab (€)" w={w} setze={setze} p={p} props={{ inputMode: "decimal", placeholder: "z. B. 2000000" }} />
        <Textfeld id={id} k="ticketMax" label="bis (€)" w={w} setze={setze} p={p} props={{ inputMode: "decimal", placeholder: "z. B. 25000000" }} />
        <Textfeld id={id} k="renditeZielPct" label="Rendite-Ziel (% p. a.)" w={w} setze={setze} p={p} props={{ inputMode: "decimal", placeholder: "z. B. 7,5" }} />
        <div className="min-w-0">
          <label htmlFor={`${id}-basis`} className={labelKlasse}>Basis des Rendite-Ziels</label>
          <select id={`${id}-basis`} value={w.renditeBasis} onChange={(e) => setze("renditeBasis", e.target.value)} className={auswahlfeld}>
            <option value="ek">Eigenkapital-IRR</option>
            <option value="projekt">Projekt-IRR</option>
          </select>
        </div>
      </div>
      <fieldset className="mt-4">
        <legend className={labelKlasse}>Deal-Struktur</legend>
        <div className="flex flex-wrap gap-2">{Object.entries(DEAL_STRUKTUREN).map(([k, t]) => <Chip key={k} name="dealStrukturen" value={k} checked={w.dealStrukturen.includes(k)} onChange={() => umschalten(setW, "dealStrukturen", k)}>{t}</Chip>)}</div>
      </fieldset>
      <div className="mt-4 min-w-0">
        <label htmlFor={`${id}-fin`} className={labelKlasse}>Finanzierungsweise</label>
        <select id={`${id}-fin`} value={w.finanzierung} onChange={(e) => setze("finanzierung", e.target.value)} className={auswahlfeld}>
          <option value="">Bitte wählen</option>
          {Object.entries(FINANZIERUNGSWEISEN).map(([k, t]) => <option key={k} value={k}>{t}</option>)}
        </select>
      </div>
      {(untertyp === "fonds" || untertyp === "stadtwerk" || w.esg.length > 0) && (
        <fieldset className="mt-4">
          <legend className={labelKlasse}>ESG-Anforderungen</legend>
          <div className="flex flex-wrap gap-2">{Object.entries(ESG_ANFORDERUNGEN).map(([k, t]) => <Chip key={k} name="esg" value={k} checked={w.esg.includes(k)} onChange={() => umschalten(setW, "esg", k)}>{t}</Chip>)}</div>
        </fieldset>
      )}
      <div className="mt-4"><FehlerBox>{s.fehler}</FehlerBox></div>
      <Absenden laeuft={s.laeuft} />
    </form>
  );
}

// ---------------------------------------------------------------- Fläche / Dach

const FLAECHE_SCHEMA = (dach) => ({
  bezeichnung: [regeln.pflicht(dach ? "Bitte geben Sie dem Dach einen Namen, z. B. „Halle Nord“." : "Bitte geben Sie der Fläche einen Namen, z. B. „Acker am Mühlweg“."), regeln.laenge(3, 120, "Die Bezeichnung")],
  plz: [(x, alle) => regeln.plz(alle?.land)(x)],
  ort: [regeln.laenge(0, 80, "Der Ort")],
  groesse: [dach ? regeln.zahl({ min: 50, max: 500000, einheit: "m²", was: "Die Dachfläche" }) : regeln.zahl({ min: 0.01, max: 100000, einheit: "ha", was: "Die Größe" })],
});

export function FlaecheFormular({ untertyp, anzahl = 0, onGespeichert }) {
  const id = useId();
  const dach = untertyp === "dach";
  const [w, setW] = useState({ bezeichnung: "", land: "DE", plz: "", ort: "", groesse: "", agri: untertyp === "landwirt" });
  const p = useFeldPruefung(FLAECHE_SCHEMA(dach));
  const s = useSenden(onGespeichert);
  const setze = (k, x) => {
    const neu = { ...w, [k]: x };
    setW(neu);
    p.aendern(k, neu);
    if (k === "land") p.aendern("plz", neu);
  };
  const absenden = (e) => {
    e.preventDefault();
    if (!p.alles(w)) return;
    const g = zahlWert(w.groesse);
    const ha = g === null ? "" : dach ? Math.round((g / 10000) * 10000) / 10000 : g;
    s.los(() => senden("/api/portal/flaechen", { body: { bezeichnung: w.bezeichnung, land: w.land, plz: w.plz, ort: w.ort, ha, agri: !dach && w.agri, nutzung: dach ? "dach" : "acker", einreichen: false } }));
  };
  return (
    <form noValidate onSubmit={absenden}>
      {anzahl > 0 && <p className="mt-4 rounded-2xl bg-ov-50 px-4 py-3 text-[14px] text-ov-900 ring-1 ring-ov-200">Sie haben bereits {anzahl} {anzahl === 1 ? "Objekt" : "Objekte"} im Portal – dieser Schritt ist erledigt. Sie können ein weiteres anlegen.</p>}
      <div className="mt-5 grid gap-4 sm:grid-cols-6">
        <Textfeld id={id} k="bezeichnung" label="Bezeichnung *" w={w} setze={setze} p={p} props={{ placeholder: dach ? "z. B. Halle Nord" : "z. B. Acker am Mühlweg", required: true }} klasse="sm:col-span-6" />
        <div className="min-w-0 sm:col-span-2">
          <label htmlFor={`${id}-land`} className={labelKlasse}>Land</label>
          <select id={`${id}-land`} value={w.land} onChange={(e) => setze("land", e.target.value)} className={auswahlfeld}>
            {Object.entries(LAENDER).map(([k, t]) => <option key={k} value={k}>{t}</option>)}
          </select>
        </div>
        <Textfeld id={id} k="plz" label="PLZ" w={w} setze={setze} p={p} props={{ inputMode: "numeric", autoComplete: "postal-code" }} klasse="sm:col-span-2" />
        <Textfeld id={id} k="groesse" label={dach ? "Dachfläche in m²" : "Größe in Hektar"} w={w} setze={setze} p={p} props={{ inputMode: "decimal", placeholder: dach ? "z. B. 4.500" : "z. B. 12,5" }} klasse="sm:col-span-2" />
        <Textfeld id={id} k="ort" label="Ort / Gemeinde" w={w} setze={setze} p={p} props={{ autoComplete: "address-level2" }} klasse="sm:col-span-6" />
      </div>
      {!dach && (
        <label className="mt-4 flex items-start gap-3 text-[14px] text-ink-700">
          <input type="checkbox" checked={w.agri} onChange={(e) => setze("agri", e.target.checked)} className="mt-0.5 h-5 w-5 rounded accent-ov-600" />
          <span>Die Fläche soll landwirtschaftlich weiter genutzt werden (Agri-PV).</span>
        </label>
      )}
      <p className="mt-3 text-[12.5px] text-ink-500">Gespeichert als Entwurf. Flurstücke, Fachangaben und Unterlagen folgen auf der Flächenseite.</p>
      <div className="mt-4"><FehlerBox>{s.fehler}</FehlerBox></div>
      <Absenden laeuft={s.laeuft} text={dach ? "Dach speichern" : "Fläche speichern"} />
    </form>
  );
}

// ---------------------------------------------------------------- Benachrichtigungen

export function BenachrichtigungenFormular({ nutzer, onGespeichert }) {
  const arten = benachrichtigungArtenFuer(nutzer.rollen || []);
  const [w, setW] = useState(() => ({ ...mailEinstellungenStandard(), ...(nutzer.mailEinstellungen || {}) }));
  const s = useSenden(onGespeichert);
  return (
    <form onSubmit={(e) => { e.preventDefault(); s.los(() => senden("/api/portal/benachrichtigungen", { method: "PUT", body: { einstellungen: Object.fromEntries(arten.map((k) => [k, !!w[k]])) } })); }}>
      <fieldset className="mt-5">
        <legend className="sr-only">E-Mail-Benachrichtigungen</legend>
        <ul className="divide-y divide-ink-100 rounded-2xl ring-1 ring-ink-200/70">
          {arten.map((k) => (
            <li key={k}>
              <label className="flex cursor-pointer items-start gap-3 px-4 py-3.5 hover:bg-sand-50">
                <input type="checkbox" checked={!!w[k]} onChange={(e) => setW((x) => ({ ...x, [k]: e.target.checked }))} className="mt-0.5 h-5 w-5 shrink-0 rounded accent-ov-600" />
                <span className="min-w-0">
                  <span className="block text-[14.5px] font-semibold text-ink-900">{BENACHRICHTIGUNG_ARTEN[k].label}</span>
                  <span className="block text-[13px] leading-snug text-ink-500">{BENACHRICHTIGUNG_ARTEN[k].text}</span>
                </span>
              </label>
            </li>
          ))}
        </ul>
      </fieldset>
      <div className="mt-4"><FehlerBox>{s.fehler}</FehlerBox></div>
      <Absenden laeuft={s.laeuft} text="Einstellungen speichern" />
    </form>
  );
}

toolu_01BxyuUw2y9qjqHBhPyx8Vjc.content:
"use client";

// Inline-Formulare der Onboarding-Assistenten (Team B1): Profil, Untertyp, Suchprofil, Ticket & Struktur, Fläche/Dach,
// Benachrichtigungen. Gespeichert wird ausschließlich über die bestehenden Portal-APIs (Rechte/Validierung dort);
// danach lädt der Assistent den Stand aus echten Daten neu.

import { useId, useState } from "react";
import Button from "@/components/ui/Button";
import { cn } from "@/components/ui/cn";
import { senden } from "@/lib/plattform/client";
import { BENACHRICHTIGUNG_ARTEN, LAENDER, PROJEKT_TYPEN, benachrichtigungArtenFuer, mailEinstellungenStandard } from "@/lib/plattform/konstanten";
import { DEAL_STRUKTUREN, ESG_ANFORDERUNGEN, FINANZIERUNGSWEISEN } from "@/lib/plattform/fach/suchprofil";
import { PHASEN } from "@/lib/invest/markt";
import { UNTERTYP_ZU_INVESTOR_TYP } from "@/lib/plattform/onboarding/pfade";
import { eingabe, auswahlfeld, labelKlasse, Chip, FehlerBox } from "@/components/Portal/felder";
import { FeldFehler, fehlerText, regeln, useFeldPruefung, zahlWert } from "../pruefung";

/** Gemeinsamer Rahmen: Absenden → API → onGespeichert() */
function useSenden(onGespeichert) {
  const [laeuft, setLaeuft] = useState(false);
  const [fehler, setFehler] = useState("");
  async function los(fn) {
    setLaeuft(true);
    setFehler("");
    try {
      await fn();
      await onGespeichert();
    } catch (e) {
      setFehler(fehlerText(e));
    } finally {
      setLaeuft(false);
    }
  }
  return { laeuft, fehler, los };
}

function Absenden({ laeuft, text = "Speichern und weiter" }) {
  return (
    <div className="mt-6 flex justify-end">
      <Button type="submit" disabled={laeuft} pfeil>{laeuft ? "Wird gespeichert …" : text}</Button>
    </div>
  );
}

function Textfeld({ id, k, label, w, setze, p, props = {}, klasse = "" }) {
  return (
    <div className={cn("min-w-0", klasse)}>
      <label htmlFor={`${id}-${k}`} className={labelKlasse}>{label}</label>
      <input id={`${id}-${k}`} value={w[k]} onChange={(e) => setze(k, e.target.value)} className={cn(eingabe, p?.fehler[k] && "ring-2 ring-red-400")} {...(p ? p.feldProps(k, `${id}-${k}`, w) : {})} {...props} />
      {p && <FeldFehler id={`${id}-${k}`} text={p.fehler[k]} />}
    </div>
  );
}

// ---------------------------------------------------------------- Untertyp

export function UntertypWahl({ schritt, pfad, onWahl }) {
  const [laeuft, setLaeuft] = useState("");
  const [fehler, setFehler] = useState("");
  return (
    <div>
      <ul className="mt-5 grid gap-3 sm:grid-cols-2" role="list">
        {pfad.untertypen.map((u) => {
          const aktiv = pfad.untertyp === u.id;
          return (
            <li key={u.id}>
              <button
                type="button"
                aria-pressed={aktiv}
                disabled={!!laeuft}
                onClick={async () => {
                  setLaeuft(u.id);
                  setFehler("");
                  try {
                    await onWahl(u.id);
                  } catch (e) {
                    setFehler(fehlerText(e));
                  } finally {
                    setLaeuft("");
                  }
                }}
                className={cn("flex h-full w-full flex-col items-start gap-1 rounded-2xl p-4 text-left ring-1 ring-inset transition-colors", aktiv ? "bg-ov-50 ring-2 ring-ov-500" : "bg-sand-50 ring-ink-200/70 hover:ring-ov-300")}
              >
                <span className="font-semibold text-ink-900">{u.label}{laeuft === u.id ? " …" : ""}</span>
                {u.text && <span className="text-[13.5px] leading-snug text-ink-600">{u.text}</span>}
              </button>
            </li>
          );
        })}
      </ul>
      {schritt.erledigt && !pfad.untertypGewaehlt && <p className="mt-3 text-[13px] text-ink-500">Vorgeschlagen aus Ihren Daten – bitte bestätigen oder ändern.</p>}
      <div className="mt-4"><FehlerBox>{fehler}</FehlerBox></div>
    </div>
  );
}

// ---------------------------------------------------------------- Profil

const PROFIL_SCHEMA = (firmaPflicht) => ({
  vorname: [regeln.pflicht("Bitte geben Sie Ihren Vornamen an."), regeln.laenge(1, 80, "Der Vorname")],
  nachname: [regeln.pflicht("Bitte geben Sie Ihren Nachnamen an."), regeln.laenge(1, 80, "Der Nachname")],
  telefon: [regeln.telefon()],
  firma: [...(firmaPflicht ? [regeln.pflicht("Bitte geben Sie die Firma bzw. Organisation an.")] : []), regeln.laenge(0, 120, "Der Name")],
});

export function ProfilFormular({ nutzer, schritt, untertyp, onGespeichert }) {
  const id = useId();
  const firmaPflicht = !!schritt.firmaLabel && untertyp !== "privat";
  const [w, setW] = useState({ vorname: nutzer.vorname || "", nachname: nutzer.nachname || "", telefon: nutzer.telefon || "", firma: nutzer.firma || "" });
  const p = useFeldPruefung(PROFIL_SCHEMA(firmaPflicht));
  const s = useSenden(onGespeichert);
  const setze = (k, v) => {
    const neu = { ...w, [k]: v };
    setW(neu);
    p.aendern(k, neu);
  };
  return (
    <form noValidate onSubmit={(e) => { e.preventDefault(); if (p.alles(w)) s.los(() => senden("/api/portal/profil", { method: "PATCH", body: w })); }}>
      <div className="mt-5 grid gap-4 sm:grid-cols-2">
        <Textfeld id={id} k="vorname" label="Vorname *" w={w} setze={setze} p={p} props={{ autoComplete: "given-name", required: true }} />
        <Textfeld id={id} k="nachname" label="Nachname *" w={w} setze={setze} p={p} props={{ autoComplete: "family-name", required: true }} />
        <Textfeld id={id} k="telefon" label="Telefon" w={w} setze={setze} p={p} props={{ autoComplete: "tel", inputMode: "tel", placeholder: "+49 …" }} />
        <Textfeld id={id} k="firma" label={`${schritt.firmaLabel || "Firma / Betrieb"}${firmaPflicht ? " *" : " (optional)"}`} w={w} setze={setze} p={p} props={{ autoComplete: "organization" }} />
      </div>
      <p className="mt-3 text-[12.5px] text-ink-500">* Pflichtangabe. E-Mail-Adresse: {nutzer.email}</p>
      <div className="mt-4"><FehlerBox>{s.fehler}</FehlerBox></div>
      <Absenden laeuft={s.laeuft} />
    </form>
  );
}

// ---------------------------------------------------------------- Suchprofil (Investor)

const SUCH_SCHEMA = {
  mwpMin: [regeln.zahl({ min: 0, max: 5000, einheit: "MWp", was: "Die Mindestgröße" })],
  mwpMax: [regeln.zahl({ min: 0, max: 5000, einheit: "MWp", was: "Die Höchstgröße" }), regeln.bereich("mwpMin", "Die Mindestgröße")],
};

const umschalten = (setW, k, wert) => setW((x) => ({ ...x, [k]: x[k].includes(wert) ? x[k].filter((y) => y !== wert) : [...x[k], wert] }));
const n0 = (x) => (zahlWert(x) === null ? null : zahlWert(x));

export function SuchprofilFormular({ nutzer, untertyp, onGespeichert }) {
  const id = useId();
  const v = nutzer.suchprofil || {};
  const [w, setW] = useState({ typen: v.typen || [], laender: v.laender || [], phasen: v.phasen || [], mwpMin: v.mwpMin ?? "", mwpMax: v.mwpMax ?? "", benachrichtigen: v.benachrichtigen ?? true });
  const p = useFeldPruefung(SUCH_SCHEMA);
  const s = useSenden(onGespeichert);
  const setze = (k, x) => {
    const neu = { ...w, [k]: x };
    setW(neu);
    p.aendern(k, neu);
    if (k === "mwpMin") p.aendern("mwpMax", neu);
  };
  const absenden = (e) => {
    e.preventDefault();
    if (!p.alles(w)) return;
    const investorTyp = UNTERTYP_ZU_INVESTOR_TYP[untertyp] && !v.investorTyp ? UNTERTYP_ZU_INVESTOR_TYP[untertyp] : v.investorTyp;
    s.los(() => senden("/api/portal/suchprofil", { method: "PUT", body: { ...v, typen: w.typen, laender: w.laender, phasen: w.phasen, mwpMin: n0(w.mwpMin), mwpMax: n0(w.mwpMax), benachrichtigen: w.benachrichtigen, investorTyp } }));
  };
  return (
    <form noValidate onSubmit={absenden}>
      <fieldset className="mt-5">
        <legend className={labelKlasse}>Projekttypen</legend>
        <div className="flex flex-wrap gap-2">{Object.entries(PROJEKT_TYPEN).map(([k, t]) => <Chip key={k} name="typen" value={k} checked={w.typen.includes(k)} onChange={() => umschalten(setW, "typen", k)}>{t}</Chip>)}</div>
      </fieldset>
      <fieldset className="mt-4">
        <legend className={labelKlasse}>Länder</legend>
        <div className="flex flex-wrap gap-2">{Object.entries(LAENDER).map(([k, t]) => <Chip key={k} name="laender" value={k} checked={w.laender.includes(k)} onChange={() => umschalten(setW, "laender", k)}>{t}</Chip>)}</div>
      </fieldset>
      <fieldset className="mt-4">
        <legend className={labelKlasse}>Projektphasen</legend>
        <div className="flex flex-wrap gap-2">{PHASEN.map((ph) => <Chip key={ph.id} name="phasen" value={ph.id} checked={w.phasen.includes(ph.id)} onChange={() => umschalten(setW, "phasen", ph.id)}>{ph.kurz}</Chip>)}</div>
      </fieldset>
      <div className="mt-4 grid gap-4 sm:grid-cols-2">
        <Textfeld id={id} k="mwpMin" label="Leistung ab (MWp)" w={w} setze={setze} p={p} props={{ inputMode: "decimal", placeholder: "z. B. 5" }} />
        <Textfeld id={id} k="mwpMax" label="Leistung bis (MWp)" w={w} setze={setze} p={p} props={{ inputMode: "decimal", placeholder: "z. B. 50" }} />
      </div>
      <label className="mt-4 flex items-start gap-3 text-[14px] text-ink-700">
        <input type="checkbox" checked={w.benachrichtigen} onChange={(e) => setW((x) => ({ ...x, benachrichtigen: e.target.checked }))} className="mt-0.5 h-5 w-5 rounded accent-ov-600" />
        <span>Bei neuen passenden Projekten benachrichtigen (ab 70 % Passung, im Profil einstellbar).</span>
      </label>
      <div className="mt-4"><FehlerBox>{s.fehler}</FehlerBox></div>
      <Absenden laeuft={s.laeuft} text="Suchprofil speichern" />
    </form>
  );
}

// ---------------------------------------------------------------- Ticket & Struktur (Investor)

const TICKET_SCHEMA = {
  ticketMin: [regeln.zahl({ min: 0, max: 1e10, einheit: "€", was: "Das Mindestticket" })],
  ticketMax: [regeln.zahl({ min: 0, max: 1e10, einheit: "€", was: "Das Höchstticket" }), regeln.bereich("ticketMin", "Das Mindestticket")],
  renditeZielPct: [regeln.zahl({ min: 0, max: 30, einheit: "%", was: "Das Rendite-Ziel" })],
};

export function TicketFormular({ nutzer, untertyp, onGespeichert }) {
  const id = useId();
  const v = nutzer.suchprofil || {};
  const [w, setW] = useState({
    ticketMin: v.ticketMin ?? "", ticketMax: v.ticketMax ?? "", renditeZielPct: v.renditeZielPct ?? "", renditeBasis: v.renditeBasis || "ek",
    dealStrukturen: v.dealStrukturen || [], finanzierung: v.finanzierung || "", esg: v.esg || [],
  });
  const p = useFeldPruefung(TICKET_SCHEMA);
  const s = useSenden(onGespeichert);
  const setze = (k, x) => {
    const neu = { ...w, [k]: x };
    setW(neu);
    p.aendern(k, neu);
    if (k === "ticketMin") p.aendern("ticketMax", neu);
  };
  const absenden = (e) => {
    e.preventDefault();
    if (!p.alles(w)) return;
    s.los(() => senden("/api/portal/suchprofil", { method: "PUT", body: { ...v, ticketMin: n0(w.ticketMin), ticketMax: n0(w.ticketMax), renditeZielPct: n0(w.renditeZielPct), renditeBasis: w.renditeBasis, dealStrukturen: w.dealStrukturen, finanzierung: w.finanzierung, esg: w.esg } }));
  };
  return (
    <form noValidate onSubmit={absenden}>
      <div className="mt-5 grid gap-4 sm:grid-cols-2">
        <Textfeld id={id} k="ticketMin" label="Eigenkapital je Transaktion ab (€)" w={w} setze={setze} p={p} props={{ inputMode: "decimal", placeholder: "z. B. 2000000" }} />
        <Textfeld id={id} k="ticketMax" label="bis (€)" w={w} setze={setze} p={p} props={{ inputMode: "decimal", placeholder: "z. B. 25000000" }} />
        <Textfeld id={id} k="renditeZielPct" label="Rendite-Ziel (% p. a.)" w={w} setze={setze} p={p} props={{ inputMode: "decimal", placeholder: "z. B. 7,5" }} />
        <div className="min-w-0">
          <label htmlFor={`${id}-basis`} className={labelKlasse}>Basis des Rendite-Ziels</label>
          <select id={`${id}-basis`} value={w.renditeBasis} onChange={(e) => setze("renditeBasis", e.target.value)} className={auswahlfeld}>
            <option value="ek">Eigenkapital-IRR</option>
            <option value="projekt">Projekt-IRR</option>
          </select>
        </div>
      </div>
      <fieldset className="mt-4">
        <legend className={labelKlasse}>Deal-Struktur</legend>
        <div className="flex flex-wrap gap-2">{Object.entries(DEAL_STRUKTUREN).map(([k, t]) => <Chip key={k} name="dealStrukturen" value={k} checked={w.dealStrukturen.includes(k)} onChange={() => umschalten(setW, "dealStrukturen", k)}>{t}</Chip>)}</div>
      </fieldset>
      <div className="mt-4 min-w-0">
        <label htmlFor={`${id}-fin`} className={labelKlasse}>Finanzierungsweise</label>
        <select id={`${id}-fin`} value={w.finanzierung} onChange={(e) => setze("finanzierung", e.target.value)} className={auswahlfeld}>
          <option value="">Bitte wählen</option>
          {Object.entries(FINANZIERUNGSWEISEN).map(([k, t]) => <option key={k} value={k}>{t}</option>)}
        </select>
      </div>
      {(untertyp === "fonds" || untertyp === "stadtwerk" || w.esg.length > 0) && (
        <fieldset className="mt-4">
          <legend className={labelKlasse}>ESG-Anforderungen</legend>
          <div className="flex flex-wrap gap-2">{Object.entries(ESG_ANFORDERUNGEN).map(([k, t]) => <Chip key={k} name="esg" value={k} checked={w.esg.includes(k)} onChange={() => umschalten(setW, "esg", k)}>{t}</Chip>)}</div>
        </fieldset>
      )}
      <div className="mt-4"><FehlerBox>{s.fehler}</FehlerBox></div>
      <Absenden laeuft={s.laeuft} />
    </form>
  );
}

// ---------------------------------------------------------------- Fläche / Dach

const FLAECHE_SCHEMA = (dach) => ({
  bezeichnung: [regeln.pflicht(dach ? "Bitte geben Sie dem Dach einen Namen, z. B. „Halle Nord“." : "Bitte geben Sie der Fläche einen Namen, z. B. „Acker am Mühlweg“."), regeln.laenge(3, 120, "Die Bezeichnung")],
  plz: [(x, alle) => regeln.plz(alle?.land)(x)],
  ort: [regeln.laenge(0, 80, "Der Ort")],
  groesse: [dach ? regeln.zahl({ min: 50, max: 500000, einheit: "m²", was: "Die Dachfläche" }) : regeln.zahl({ min: 0.01, max: 100000, einheit: "ha", was: "Die Größe" })],
});

export function FlaecheFormular({ untertyp, anzahl = 0, onGespeichert }) {
  const id = useId();
  const dach = untertyp === "dach";
  const [w, setW] = useState({ bezeichnung: "", land: "DE", plz: "", ort: "", groesse: "", agri: untertyp === "landwirt" });
  const p = useFeldPruefung(FLAECHE_SCHEMA(dach));
  const s = useSenden(onGespeichert);
  const setze = (k, x) => {
    const neu = { ...w, [k]: x };
    setW(neu);
    p.aendern(k, neu);
    if (k === "land") p.aendern("plz", neu);
  };
  const absenden = (e) => {
    e.preventDefault();
    if (!p.alles(w)) return;
    const g = zahlWert(w.groesse);
    const ha = g === null ? "" : dach ? Math.round((g / 10000) * 10000) / 10000 : g;
    s.los(() => senden("/api/portal/flaechen", { body: { bezeichnung: w.bezeichnung, land: w.land, plz: w.plz, ort: w.ort, ha, agri: !dach && w.agri, nutzung: dach ? "dach" : "acker", einreichen: false } }));
  };
  return (
    <form noValidate onSubmit={absenden}>
      {anzahl > 0 && <p className="mt-4 rounded-2xl bg-ov-50 px-4 py-3 text-[14px] text-ov-900 ring-1 ring-ov-200">Sie haben bereits {anzahl} {anzahl === 1 ? "Objekt" : "Objekte"} im Portal – dieser Schritt ist erledigt. Sie können ein weiteres anlegen.</p>}
      <div className="mt-5 grid gap-4 sm:grid-cols-6">
        <Textfeld id={id} k="bezeichnung" label="Bezeichnung *" w={w} setze={setze} p={p} props={{ placeholder: dach ? "z. B. Halle Nord" : "z. B. Acker am Mühlweg", required: true }} klasse="sm:col-span-6" />
        <div className="min-w-0 sm:col-span-2">
          <label htmlFor={`${id}-land`} className={labelKlasse}>Land</label>
          <select id={`${id}-land`} value={w.land} onChange={(e) => setze("land", e.target.value)} className={auswahlfeld}>
            {Object.entries(LAENDER).map(([k, t]) => <option key={k} value={k}>{t}</option>)}
          </select>
        </div>
        <Textfeld id={id} k="plz" label="PLZ" w={w} setze={setze} p={p} props={{ inputMode: "numeric", autoComplete: "postal-code" }} klasse="sm:col-span-2" />
        <Textfeld id={id} k="groesse" label={dach ? "Dachfläche in m²" : "Größe in Hektar"} w={w} setze={setze} p={p} props={{ inputMode: "decimal", placeholder: dach ? "z. B. 4.500" : "z. B. 12,5" }} klasse="sm:col-span-2" />
        <Textfeld id={id} k="ort" label="Ort / Gemeinde" w={w} setze={setze} p={p} props={{ autoComplete: "address-level2" }} klasse="sm:col-span-6" />
      </div>
      {!dach && (
        <label className="mt-4 flex items-start gap-3 text-[14px] text-ink-700">
          <input type="checkbox" checked={w.agri} onChange={(e) => setze("agri", e.target.checked)} className="mt-0.5 h-5 w-5 rounded accent-ov-600" />
          <span>Die Fläche soll landwirtschaftlich weiter genutzt werden (Agri-PV).</span>
        </label>
      )}
      <p className="mt-3 text-[12.5px] text-ink-500">Gespeichert als Entwurf. Flurstücke, Fachangaben und Unterlagen folgen auf der Flächenseite.</p>
      <div className="mt-4"><FehlerBox>{s.fehler}</FehlerBox></div>
      <Absenden laeuft={s.laeuft} text={dach ? "Dach speichern" : "Fläche speichern"} />
    </form>
  );
}

// ---------------------------------------------------------------- Benachrichtigungen

export function BenachrichtigungenFormular({ nutzer, onGespeichert }) {
  const arten = benachrichtigungArtenFuer(nutzer.rollen || []);
  const [w, setW] = useState(() => ({ ...mailEinstellungenStandard(), ...(nutzer.mailEinstellungen || {}) }));
  const s = useSenden(onGespeichert);
  return (
    <form onSubmit={(e) => { e.preventDefault(); s.los(() => senden("/api/portal/benachrichtigungen", { method: "PUT", body: { einstellungen: Object.fromEntries(arten.map((k) => [k, !!w[k]])) } })); }}>
      <fieldset className="mt-5">
        <legend className="sr-only">E-Mail-Benachrichtigungen</legend>
        <ul className="divide-y divide-ink-100 rounded-2xl ring-1 ring-ink-200/70">
          {arten.map((k) => (
            <li key={k}>
              <label className="flex cursor-pointer items-start gap-3 px-4 py-3.5 hover:bg-sand-50">
                <input type="checkbox" checked={!!w[k]} onChange={(e) => setW((x) => ({ ...x, [k]: e.target.checked }))} className="mt-0.5 h-5 w-5 shrink-0 rounded accent-ov-600" />
                <span className="min-w-0">
                  <span className="block text-[14.5px] font-semibold text-ink-900">{BENACHRICHTIGUNG_ARTEN[k].label}</span>
                  <span className="block text-[13px] leading-snug text-ink-500">{BENACHRICHTIGUNG_ARTEN[k].text}</span>
                </span>
              </label>
            </li>
          ))}
        </ul>
      </fieldset>
      <div className="mt-4"><FehlerBox>{s.fehler}</FehlerBox></div>
      <Absenden laeuft={s.laeuft} text="Einstellungen speichern" />
    </form>
  );
}

input.content:
"use client";

// Onboarding-Assistent je Rolle und Untertyp (Team B1). Rendert jeden deklarativen Pfad (lib/plattform/onboarding/pfade):
// Schrittliste mit Status (erledigt aus echten Daten, „später“, Pflicht), Inhalt je Schritt (Inline-Formular, Aktion mit
// Links, Info mit „Verstanden“), Wechsel des Untertyps bzw. Pfads, Abschluss nur bei erfüllten Pflichtkriterien.
// Jede Änderung geht an /api/portal/onboarding (Server prüft); danach wird der Stand neu ausgewertet.

import { useCallback, useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { ArrowLeft, ArrowRight, Check, Clock, Compass, ExternalLink, RefreshCw } from "lucide-react";
import Button from "@/components/ui/Button";
import { cn } from "@/components/ui/cn";
import { senden } from "@/lib/plattform/client";
import { FehlerBox } from "@/components/Portal/felder";
import BegriffPopover from "../BegriffPopover";
import { fehlerText } from "../pruefung";
import { BenachrichtigungenFormular, FlaecheFormular, ProfilFormular, SuchprofilFormular, TicketFormular, UntertypWahl } from "./Formulare";

async function aktion(body) {
  return senden("/api/portal/onboarding", { method: "PUT", body });
}

export default function Assistent({ nutzer: nutzerStart, start, pfade, startSchritt = null, begriffe = {}, anzahl = {} }) {
  const router = useRouter();
  const [pfad, setPfad] = useState(start);
  const [nutzer, setNutzer] = useState(nutzerStart);
  const [aktivId, setAktivId] = useState(() => (start.schritte.some((s) => s.id === startSchritt) ? startSchritt : start.naechster || start.schritte[0]?.id));
  const [laeuft, setLaeuft] = useState("");
  const [fehler, setFehler] = useState("");
  const [abschlussOffen, setAbschlussOffen] = useState(false);
  const kopfRef = useRef(null);
  const ersterRender = useRef(true);

  const index = Math.max(0, pfad.schritte.findIndex((s) => s.id === aktivId));
  const schritt = pfad.schritte[index] || pfad.schritte[0];

  useEffect(() => {
    if (ersterRender.current) {
      ersterRender.current = false;
      return;
    }
    kopfRef.current?.focus();
  }, [aktivId, abschlussOffen]);

  /** Stand neu laden (echte Daten) und optional zum nächsten offenen Schritt springen */
  const neuLaden = useCallback(async (weiterNach = null) => {
    const r = await senden("/api/portal/onboarding?ansicht=assistent", { method: "GET" });
    if (!r?.pfad) return;
    setPfad(r.pfad);
    const me = await senden("/api/auth/ich", { method: "GET" }).catch(() => null);
    if (me?.nutzer) setNutzer(me.nutzer);
    if (weiterNach) {
      const i = r.pfad.schritte.findIndex((s) => s.id === weiterNach);
      const folgend = r.pfad.schritte.slice(i + 1).find((s) => !s.erledigt) || r.pfad.schritte.find((s) => !s.erledigt && !s.spaeter);
      if (folgend) setAktivId(folgend.id);
      else setAbschlussOffen(true);
    }
    router.refresh();
  }, [router]);

  async function ausfuehren(schluessel, body, weiterNach = null) {
    setLaeuft(schluessel);
    setFehler("");
    try {
      const r = await aktion(body);
      if (r?.pfad) setPfad(r.pfad);
      if (weiterNach) {
        const liste = r?.pfad?.schritte || pfad.schritte;
        const i = liste.findIndex((s) => s.id === weiterNach);
        const folgend = liste.slice(i + 1).find((s) => !s.erledigt) || liste.find((s) => !s.erledigt && !s.spaeter && s.id !== weiterNach);
        if (folgend) setAktivId(folgend.id);
        else setAbschlussOffen(true);
      }
      return r;
    } catch (e) {
      setFehler(fehlerText(e));
      return null;
    } finally {
      setLaeuft("");
    }
  }

  const gehe = (id) => {
    setAbschlussOffen(false);
    setFehler("");
    setAktivId(id);
  };

  const pflichtOffen = pfad.schritte.filter((s) => s.pflicht && !s.erledigt);

  return (
    <div className="mx-auto max-w-[1100px]">
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div className="min-w-0">
          <p className="text-[12px] font-semibold uppercase tracking-[0.16em] text-ov-700">Geführter Einstieg{pfad.untertyp ? ` · ${pfad.untertypen.find((u) => u.id === pfad.untertyp)?.label || ""}` : ""}</p>
          <p className="mt-1 font-display text-[20px] font-bold leading-tight text-ink-900 md:text-[22px]">{pfad.titel}</p>
          <p className="mt-1 max-w-[70ch] text-[14px] leading-relaxed text-ink-600">{pfad.text}</p>
        </div>
        <Link href="/portal" className="text-[13.5px] font-semibold text-ink-500 underline-offset-4 hover:text-ink-800 hover:underline">Später fortsetzen</Link>
      </div>

      {pfade.length > 1 && (
        <div className="mt-4 flex flex-wrap items-center gap-2" role="group" aria-label="Einstieg wechseln">
          <span className="text-[13px] text-ink-500">Ihre Rollen:</span>
          {pfade.map((p) => (
            <button
              key={p.id}
              type="button"
              aria-pressed={p.id === pfad.id}
              disabled={!!laeuft}
              onClick={async () => {
                if (p.id === pfad.id) return;
                const r = await ausfuehren(`pfad-${p.id}`, { aktion: "pfad", pfad: p.id });
                if (r?.pfad) gehe(r.pfad.naechster || r.pfad.schritte[0]?.id);
              }}
              className={cn("rounded-full px-3 py-1.5 text-[13px] font-semibold ring-1 ring-inset", p.id === pfad.id ? "bg-navy-900 text-white ring-navy-900" : "bg-white text-ink-700 ring-ink-200 hover:ring-ov-300")}
            >
              {p.titel.replace(/^Einstieg für |^Einarbeitung im /, "")}
            </button>
          ))}
        </div>
      )}

      {/* Fortschritt */}
      <div className="mt-5">
        <div className="flex items-center justify-between text-[13px] text-ink-600">
          <span>{pfad.erledigt} von {pfad.gesamt} erledigt</span>
          <span>{pflichtOffen.length ? `${pflichtOffen.length} Pflicht${pflichtOffen.length === 1 ? "schritt" : "schritte"} offen` : "Alle Pflichtschritte erledigt"}</span>
        </div>
        <div className="mt-1.5 h-2 rounded-full bg-ink-100" role="progressbar" aria-valuemin={0} aria-valuemax={100} aria-valuenow={pfad.quote} aria-label="Fortschritt des Einstiegs">
          <div className="h-2 rounded-full bg-ov-500 transition-[width] duration-500" style={{ width: `${Math.max(4, pfad.quote)}%` }} />
        </div>
      </div>

      <div className="mt-6 grid gap-6 lg:grid-cols-[280px_minmax(0,1fr)]">
        {/* Schrittliste */}
        <nav aria-label="Schritte des Einstiegs" className="min-w-0">
          <ol className="flex gap-2 overflow-x-auto pb-1 lg:flex-col lg:overflow-visible lg:pb-0">
            {pfad.schritte.map((s, i) => {
              const aktiv = !abschlussOffen && s.id === schritt.id;
              return (
                <li key={s.id} className="shrink-0 lg:shrink">
                  <button
                    type="button"
                    onClick={() => gehe(s.id)}
                    aria-current={aktiv ? "step" : undefined}
                    className={cn("flex w-full items-center gap-2.5 rounded-2xl px-3 py-2 text-left text-[13.5px] ring-1 ring-inset transition-colors", aktiv ? "bg-white font-semibold text-ink-900 ring-ov-400" : "bg-white/60 text-ink-700 ring-ink-200/70 hover:ring-ov-300")}
                  >
                    <span className={cn("flex h-6 w-6 shrink-0 items-center justify-center rounded-full text-[11px] font-bold", s.erledigt ? "bg-ov-500 text-white" : s.spaeter ? "bg-sun-100 text-ink-700" : aktiv ? "bg-navy-900 text-white" : "bg-ink-100 text-ink-500")}>
                      {s.erledigt ? <Check aria-hidden="true" className="h-3.5 w-3.5" strokeWidth={3} /> : s.spaeter ? <Clock aria-hidden="true" className="h-3.5 w-3.5" /> : i + 1}
                    </span>
                    <span className="min-w-0 whitespace-nowrap lg:whitespace-normal">
                      {s.kurz}
                      {s.pflicht && !s.erledigt && <span className="ml-1 text-ov-700" aria-hidden="true">*</span>}
                      <span className="sr-only">{s.erledigt ? " – erledigt" : s.spaeter ? " – auf später gesetzt" : " – offen"}{s.pflicht ? ", Pflicht" : ""}</span>
                    </span>
                  </button>
                </li>
              );
            })}
            <li className="shrink-0 lg:shrink">
              <button type="button" onClick={() => setAbschlussOffen(true)} aria-current={abschlussOffen ? "step" : undefined} className={cn("flex w-full items-center gap-2.5 rounded-2xl px-3 py-2 text-left text-[13.5px] ring-1 ring-inset", abschlussOffen ? "bg-white font-semibold text-ink-900 ring-ov-400" : "bg-white/60 text-ink-700 ring-ink-200/70 hover:ring-ov-300")}>
                <span className={cn("flex h-6 w-6 shrink-0 items-center justify-center rounded-full", pfad.abgeschlossen ? "bg-ov-500 text-white" : "bg-ink-100 text-ink-500")}><Compass aria-hidden="true" className="h-3.5 w-3.5" /></span>
                <span className="whitespace-nowrap">Abschluss</span>
              </button>
            </li>
          </ol>
          <p className="mt-2 hidden text-[12px] text-ink-500 lg:block"><span className="text-ov-700">*</span> Pflicht für ein arbeitsfähiges Konto</p>
        </nav>

        <section aria-labelledby="einstieg-titel" className="min-w-0 rounded-3xl bg-white p-5 ring-1 ring-ink-200/70 sm:p-8">
          {abschlussOffen ? (
            <Abschluss pfad={pfad} kopfRef={kopfRef} pflichtOffen={pflichtOffen} gehe={gehe} laeuft={laeuft} fehler={fehler}
              abschliessen={async () => {
                const r = await ausfuehren("abschliessen", { aktion: "abschliessen", pfad: pfad.id });
                if (r) {
                  router.push("/portal?hinweis=einstieg-fertig");
                  router.refresh();
                }
              }}
            />
          ) : (
            <div>
              <div className="flex flex-wrap items-center gap-2">
                <span className="text-[12.5px] font-semibold text-ink-500">Schritt {index + 1} von {pfad.schritte.length}</span>
                {schritt.pflicht && <span className="rounded-full bg-ov-50 px-2 py-0.5 text-[11.5px] font-semibold text-ov-800 ring-1 ring-ov-200">Pflicht</span>}
                {schritt.erledigt && <span className="rounded-full bg-ov-500 px-2 py-0.5 text-[11.5px] font-semibold text-white">Erledigt</span>}
                {schritt.spaeter && <span className="rounded-full bg-sun-100 px-2 py-0.5 text-[11.5px] font-semibold text-ink-800">Auf später gesetzt</span>}
              </div>
              <h1 id="einstieg-titel" ref={kopfRef} tabIndex={-1} className="mt-2 font-display text-[24px] font-extrabold leading-tight tracking-tight text-ink-900 outline-none md:text-[28px]">
                {schritt.titel}
                {schritt.begriff && begriffe[schritt.begriff] && <span className="ml-2 align-middle text-[16px]"><BegriffPopover eintrag={begriffe[schritt.begriff]} /></span>}
              </h1>
              {schritt.text && <p className="mt-2 text-[15px] leading-relaxed text-ink-600">{schritt.text}</p>}
              {schritt.punkte.length > 0 && (
                <ul className="mt-4 space-y-2">
                  {schritt.punkte.map((p) => (
                    <li key={p} className="flex gap-2.5 text-[14px] leading-relaxed text-ink-700">
                      <Check aria-hidden="true" className="mt-1 h-4 w-4 shrink-0 text-ov-600" />
                      <span>{p}</span>
                    </li>
                  ))}
                </ul>
              )}

              <SchrittInhalt schritt={schritt} pfad={pfad} nutzer={nutzer} anzahl={anzahl}
                onGespeichert={() => neuLaden(schritt.id)}
                onUntertyp={async (u) => {
                  const r = await aktion({ aktion: "untertyp", pfad: pfad.id, untertyp: u });
                  if (r?.pfad) {
                    setPfad(r.pfad);
                    const folgend = r.pfad.schritte.find((s) => !s.erledigt && s.id !== "typ");
                    if (folgend) setAktivId(folgend.id);
                  }
                }}
              />

              {schritt.links.length > 0 && (
                <div className="mt-6 flex flex-wrap gap-3">
                  {schritt.links.map((l) => (
                    <Button key={l.href} href={l.href} variant={l.primaer ? "primary" : "secondary"} size="sm">
                      {l.label} {!l.href.startsWith("/portal") && <ExternalLink aria-hidden="true" className="ml-1 inline h-3.5 w-3.5" />}
                    </Button>
                  ))}
                </div>
              )}
              {schritt.art === "aktion" && !schritt.erledigt && (
                <p className="mt-3 flex flex-wrap items-center gap-2 text-[13px] text-ink-500">
                  Erledigt wird der Schritt automatisch, sobald die Angaben im Portal vorliegen.
                  <button type="button" onClick={async () => { setLaeuft("pruefen"); try { await neuLaden(); } finally { setLaeuft(""); } }} className="inline-flex items-center gap-1 font-semibold text-ov-700 hover:text-ov-800">
                    <RefreshCw aria-hidden="true" className={cn("h-3.5 w-3.5", laeuft === "pruefen" && "animate-spin")} /> Stand prüfen
                  </button>
                </p>
              )}

              <div className="mt-4"><FehlerBox>{fehler}</FehlerBox></div>

              <div className="mt-8 flex flex-col-reverse gap-3 border-t border-ink-100 pt-5 sm:flex-row sm:items-center sm:justify-between">
                <div className="flex flex-wrap gap-2">
                  {index > 0 && (
                    <button type="button" onClick={() => gehe(pfad.schritte[index - 1].id)} className="inline-flex h-11 items-center gap-1.5 rounded-full px-4 text-[14.5px] font-semibold text-ink-600 hover:bg-ink-100 hover:text-ink-900">
                      <ArrowLeft aria-hidden="true" className="h-4 w-4" /> Zurück
                    </button>
                  )}
                  {!schritt.erledigt && !schritt.spaeter && (
                    <button type="button" disabled={!!laeuft} onClick={() => ausfuehren("spaeter", { aktion: "spaeter", pfad: pfad.id, schritt: schritt.id }, schritt.id)} className="inline-flex h-11 items-center gap-1.5 rounded-full px-4 text-[14.5px] font-semibold text-ink-600 hover:bg-ink-100 hover:text-ink-900">
                      <Clock aria-hidden="true" className="h-4 w-4" /> Später
                    </button>
                  )}
                </div>
                <div className="flex flex-wrap gap-2 sm:justify-end">
                  {schritt.bestaetigbar && !schritt.erledigt && (
                    <Button variant={schritt.art === "info" ? "primary" : "secondary"} disabled={!!laeuft} onClick={() => ausfuehren("bestaetigen", { aktion: "bestaetigen", pfad: pfad.id, schritt: schritt.id }, schritt.id)}>
                      {laeuft === "bestaetigen" ? "Wird gespeichert …" : schritt.bestaetigenText || "Verstanden"}
                    </Button>
                  )}
                  {(schritt.erledigt || !schritt.bestaetigbar || schritt.art !== "info") && (
                    <Button variant={schritt.erledigt ? "primary" : "ghost"} pfeil onClick={() => (index < pfad.schritte.length - 1 ? gehe(pfad.schritte[index + 1].id) : setAbschlussOffen(true))}>
                      {index < pfad.schritte.length - 1 ? "Weiter" : "Zum Abschluss"}
                    </Button>
                  )}
                </div>
              </div>
            </div>
          )}
        </section>
      </div>
    </div>
  );
}

function SchrittInhalt({ schritt, pfad, nutzer, anzahl, onGespeichert, onUntertyp }) {
  switch (schritt.formular) {
    case "untertyp":
      return <UntertypWahl schritt={schritt} pfad={pfad} onWahl={onUntertyp} />;
    case "profil":
      return <ProfilFormular key={`profil-${pfad.untertyp}`} nutzer={nutzer} schritt={schritt} untertyp={pfad.untertyp} onGespeichert={onGespeichert} />;
    case "suchprofil":
      return <SuchprofilFormular nutzer={nutzer} untertyp={pfad.untertyp} onGespeichert={onGespeichert} />;
    case "ticket":
      return <TicketFormular nutzer={nutzer} untertyp={pfad.untertyp} onGespeichert={onGespeichert} />;
    case "flaeche":
      return <FlaecheFormular key={`flaeche-${pfad.untertyp}`} untertyp={pfad.untertyp} anzahl={anzahl.flaechen || 0} onGespeichert={onGespeichert} />;
    case "benachrichtigungen":
      return <BenachrichtigungenFormular nutzer={nutzer} onGespeichert={onGespeichert} />;
    default:
      return null;
  }
}

function Abschluss({ pfad, kopfRef, pflichtOffen, gehe, laeuft, fehler, abschliessen }) {
  const offenOptional = pfad.schritte.filter((s) => !s.pflicht && !s.erledigt);
  return (
    <div>
      <h1 id="einstieg-titel" ref={kopfRef} tabIndex={-1} className="font-display text-[24px] font-extrabold leading-tight tracking-tight text-ink-900 outline-none md:text-[28px]">
        {pfad.abgeschlossen ? "Einstieg abgeschlossen" : pflichtOffen.length ? "Fast geschafft" : "Alles bereit"}
      </h1>
      <p className="mt-2 text-[15px] leading-relaxed text-ink-600">
        {pflichtOffen.length
          ? "Abschließen können Sie, sobald alle Pflichtschritte erledigt sind – geprüft wird an Ihren echten Daten, nicht am Klick."
          : "Ihr Konto ist arbeitsfähig. Offene freiwillige Punkte bleiben in der Checkliste „Erste Schritte“ auf der Übersicht."}
      </p>
      {pflichtOffen.length > 0 && (
        <ul className="mt-5 space-y-2">
          {pflichtOffen.map((s) => (
            <li key={s.id}>
              <button type="button" onClick={() => gehe(s.id)} className="flex w-full items-center justify-between gap-3 rounded-2xl bg-sand-50 px-4 py-3 text-left ring-1 ring-ink-200/70 hover:ring-ov-300">
                <span className="font-semibold text-ink-900">{s.titel}</span>
                <ArrowRight aria-hidden="true" className="h-4 w-4 shrink-0 text-ink-400" />
              </button>
            </li>
          ))}
        </ul>
      )}
      {!pflichtOffen.length && offenOptional.length > 0 && (
        <p className="mt-4 text-[13.5px] text-ink-500">Noch freiwillig offen: {offenOptional.map((s) => s.kurz).join(", ")}.</p>
      )}
      <div className="mt-4"><FehlerBox>{fehler}</FehlerBox></div>
      <div className="mt-8 flex flex-col gap-3 border-t border-ink-100 pt-5 sm:flex-row sm:justify-end">
        <Button variant="secondary" href="/portal/hilfe">Hilfe ansehen</Button>
        {pfad.abgeschlossen ? (
          <Button href={pfad.id === "backoffice" ? "/portal/admin" : "/portal"} pfeil>{pfad.id === "backoffice" ? "Zum Cockpit" : "Zur Übersicht"}</Button>
        ) : (
          <Button pfeil disabled={!!laeuft || pflichtOffen.length > 0} onClick={abschliessen}>{laeuft === "abschliessen" ? "Wird geprüft …" : "Einstieg abschließen"}</Button>
        )}
      </div>
    </div>
  );
}

